// Decide qué facturas vencidas reciben gestión hoy y con qué tono. Sin estado ni base de datos.
// Calendario de cobro: días de mora en los que toca recordatorio. Cámbialo aquí si tu política es otra.
const CALENDARIO = {
  amable: [1, 7],
  firme: [15, 22],
  escalarDesde: 30, // desde este día de mora se escala al responsable…
  escalarCada: 7, // …y se repite cada tantos días
};

const hoy = $now.startOf('day');
// El flujo corre de lunes a viernes. Los lunes revisa también el sábado y el domingo (ventana de 3 días)
// para no perder recordatorios ni escalamientos que cayeron en fin de semana. Los demás días, solo hoy.
const ventana = hoy.weekday === 1 ? 3 : 1;

function fecha(valor) {
  const texto = String(valor ?? '').trim();
  const dma = texto.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (dma) return DateTime.fromObject({ year: +dma[3], month: +dma[2], day: +dma[1] });
  return DateTime.fromISO(texto.slice(0, 10));
}

// Etapa que corresponde a un día de mora exacto, o null si ese día no toca recordatorio
function etapaDelDia(dia) {
  if (CALENDARIO.amable.includes(dia)) return 'amable';
  if (CALENDARIO.firme.includes(dia)) return 'firme';
  if (dia >= CALENDARIO.escalarDesde && (dia - CALENDARIO.escalarDesde) % CALENDARIO.escalarCada === 0) return 'escalar';
  return null;
}

// Revisa los días de mora de la ventana (hoy y, si es lunes, el sábado y el domingo).
// Si varios tocan recordatorio, gana el día más alto.
function etapaEnVentana(diasHoy) {
  for (let dia = diasHoy; dia > diasHoy - ventana; dia--) {
    if (dia < 1) break;
    const etapa = etapaDelDia(dia);
    if (etapa) return etapa;
  }
  return null;
}

const dinero = new Intl.NumberFormat('es', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const salida = [];
for (const { json: f } of $input.all()) {
  const estado = String(f.Estado ?? '').trim().toLowerCase();
  if (!f['Número'] || estado.startsWith('pagad')) continue;
  const vence = fecha(f.Vencimiento);
  if (!vence.isValid) continue;
  const dias = Math.round(hoy.diff(vence.startOf('day'), 'days').days);
  const tono = etapaEnVentana(dias);
  if (!tono) continue;

  salida.push({
    json: {
      numero: String(f['Número']),
      cliente: f.Cliente,
      correo: String(f.Correo ?? '').trim(),
      responsable: String(f.Responsable ?? '').trim(),
      monto: '$' + dinero.format(Number(f.Monto) || 0),
      vencimiento: vence.setLocale('es').toFormat("d 'de' LLLL"),
      dias,
      etapa: tono,
    },
  });
}
return salida;
